247			}
248			scanned++
249			report := func(pos token.Pos, what string) {
250				t.Errorf("%s: %s in a migrated view (A-16 criterion 2b/3)", fset.Position(pos), what)
251			}
252			isFrame := func(name string) bool {
253				return name == "Frame" || name == "frame" || name == "SpinnerFrame"
254			}
255			ast.Inspect(file, func(n ast.Node) bool {
256				switch x := n.(type) {
257				case *ast.CallExpr:
258					if sel, ok := x.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "AdvanceSpinner" {
259						report(x.Pos(), "call to AdvanceSpinner")
260					}
261				case *ast.KeyValueExpr:
262					if id, ok := x.Key.(*ast.Ident); ok {
263						if id.Name == "StatusColumn" {
264							report(id.Pos(), "StatusColumn: key")
265						}
266						if isFrame(id.Name) {
267							report(id.Pos(), "frame field "+id.Name+": set")
268						}
269					}
270				case *ast.Field:
271					for _, id := range x.Names {
272						if isFrame(id.Name) {
273							report(id.Pos(), "frame field "+id.Name)
274						}
275					}
276				case *ast.SelectorExpr:
277					if isFrame(x.Sel.Name) {
278						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
279					}
280				case *ast.BasicLit:
281					if x.Kind == token.STRING {
282						s, err := strconv.Unquote(x.Value)
283						if err == nil && strings.ContainsAny(s, activityGlyphs) {
284							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
285						}
286					}
287				}
288				return true
289			})
290		})
291		if scanned == 0 {
292			t.Fatalf("no source file found under %v: the scan reads nothing", migratedSourceDirs)
293		}
294	}
