296	func hasAnyPrefix(s string, prefixes []string) bool {
297		for _, p := range prefixes {
298			if strings.HasPrefix(s, p) {
299				return true
300			}
301		}
302		return false
303	}
304	
305	func contains(list []string, s string) bool {
306		for _, x := range list {
307			if x == s {
308				return true
309			}
310		}
311		return false
312	}
313	
314	func sortedKeys(m map[string]datatable.ActivityTable) []string {
315		out := make([]string, 0, len(m))
316		for k := range m {
317			out = append(out, k)
318		}
319		sort.Strings(out)
320		return out
321	}
