			for _, b := range []bool{migrated, waiting, exempt} {
				if b {
					n++
				}
			}
			switch {
			case n == 0:
				t.Errorf("view %q is neither migrated, pending (with its story) nor exempt (with its reason): classify it in activity_guard_test.go", vt)
			case n > 1:
				t.Errorf("view %q is classified more than once (migrated=%v pending=%v exempt=%v)", vt, migrated, waiting, exempt)
			}
