}

// Criterion 6, other direction: a pending or exempt view that already reports
// activity tables has been migrated; its exception must go.
func TestActivityGuardNoStaleException(t *testing.T) {
	for vt, tables := range pendingViews() {
		t.Run("pending/"+string(vt), func(t *testing.T) {
			if av, ok := builtView(t, vt).(activityView); ok && len(av.ActivityTables()) > 0 {
				t.Errorf("view %q exposes ActivityTables() but is still pending (%v): remove the exception", vt, tables)
			}
		})
	}
	for vt := range exemptViews {
		t.Run("exempt/"+string(vt), func(t *testing.T) {
			if _, ok := builtView(t, vt).(activityView); ok {
				t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
			}
		})
