20	// A-16 (DEVDESK-143), skeleton delivered with the :jobs pilot (DEVDESK-142).
21	//
22	// The guard answers one question for every view the router can build: is it on
23	// the activity column, is it waiting for its migration, or is it exempt for a
24	// stated reason? A view that is none of the three fails the test by name. It
25	// is a skeleton: DEVDESK-143 completes it (footer half of criterion 5,
26	// criterion 7).
27	
28	// activityView is what a migrated view exposes to the guard: read-only tables,
29	// keyed "<view>/<table>".
30	type activityView interface {
31		ActivityTables() map[string]datatable.ActivityTable
32	}
33	
34	// migratedTables are the tables already on the activity column, by view.
35	var migratedTables = map[command.ViewType][]string{
36		command.ViewJobs: {"jobs/runs", "jobs/targets"},
37	}
38	
39	// pendingTable is a table that still has to move to the activity column.
40	type pendingTable struct {
41		Table string
42		View  command.ViewType
43		Story string
44	}
45	
46	// pendingTables may only shrink: each migration story removes its own entries.
47	var pendingTables = []pendingTable{
48		{"ws", command.ViewWorkspaces, "A-07"},
49		{"sec/inventory", command.ViewSecurity, "A-08"},
50		{"oci/images", command.ViewOCIResources, "A-09a"},
51		{"oci/registry-browser", command.ViewOCIResources, "A-09a"},
52		{"oci/networks", command.ViewOCIResources, "A-09b"},
53		{"oci/volumes", command.ViewOCIResources, "A-09b"},
54		{"oci/registries", command.ViewOCIResources, "A-09b"},
55		{"explorer/tree", command.ViewGitExplorer, "A-10a"},
56		{"explorer/clone-list", command.ViewGitExplorer, "A-10b"},
57		{"templates", command.ViewTemplates, "A-11"},
58		{"netdiag/ports", command.ViewNetdiag, "A-12"},
59		{"agent-usage/agents", command.ViewAgentUsage, "A-13"},
60		{"containers", command.ViewContainers, "A-14"},
61	}
62	
63	// maxPendingTables is the ceiling: adding an exception fails review, removing
64	// one is the only allowed change. Lower it with every migration.
65	const maxPendingTables = 13
66	
67	// exemptViews have no long-running operation to show per row (inventory:
68	// "sans objet" or out of the batch), each with its reason.
69	var exemptViews = map[command.ViewType]string{
70		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
71		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
72		command.ViewGitAuth:       "a form, no table",
