87	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
88		if got := len(pendingTables); got > maxPendingTables {
89			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
90		}
91		seen := map[string]bool{}
92		for _, p := range pendingTables {
93			if p.Story == "" {
94				t.Errorf("pending table %q names no story", p.Table)
95			}
96			if seen[p.Table] {
97				t.Errorf("pending table %q is listed twice", p.Table)
98			}
99			seen[p.Table] = true
100		}
101	}
