103	// builtView returns the view the router builds for vt, laid out at 60x30.
104	func builtView(t *testing.T, vt command.ViewType) tea.Model {
105		t.Helper()
106		a := routerAt(t, &bareView{}, 60, 30) // isolateHome, session-only secrets
107		a.createView(vt)
108		m := a.views[vt]
109		if m == nil {
