116	// Criterion 6: every view the router builds is migrated, pending or exempt.
117	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
118		pending := pendingViews()
119		for _, name := range command.AllViewNames() {
120			vt := command.ViewType(name)
121			t.Run(name, func(t *testing.T) {
122				_, migrated := migratedTables[vt]
123				_, waiting := pending[vt]
124				_, exempt := exemptViews[vt]
125				n := 0
126				for _, b := range []bool{migrated, waiting, exempt} {
127					if b {
128						n++
129					}
130				}
131				switch {
132				case n == 0:
133					t.Errorf("view %q is neither migrated, pending (with its story) nor exempt (with its reason): classify it in activity_guard_test.go", vt)
134				case n > 1:
135					t.Errorf("view %q is classified more than once (migrated=%v pending=%v exempt=%v)", vt, migrated, waiting, exempt)
136				}
137			})
138		}
139	}
