141	// Criteria 1, 4 and the help half of 5, at runtime, on the views the router builds.
142	func TestActivityGuardMigratedViews(t *testing.T) {
143		legendTitle := indicator.Legend().Title
144		for vt, want := range migratedTables {
145			t.Run(string(vt), func(t *testing.T) {
146				m := builtView(t, vt)
147				av, ok := m.(activityView)
148				if !ok {
149					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
150				}
151				tables := av.ActivityTables()
152				for _, name := range want {
153					tb, ok := tables[name]
154					if !ok {
155						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
