195		for vt := range exemptViews {
196			t.Run("exempt/"+string(vt), func(t *testing.T) {
197				if _, ok := builtView(t, vt).(activityView); ok {
198					t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
199				}
200			})
201		}
202	}
